// Type pour les messages d'erreur/succès
type Message = {
  message: string;
  type: 'error' | 'success';
};

export default function LoginPage() {
  const router = useRouter();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [messages, setMessages] = useState([]);

  const submitLogin = async (e: FormEvent) => {
    e.preventDefault();
    const tempMessages: Message[] = [];

    if (!email.trim()) tempMessages.push({ message: 'Your e-mail is missing', type: 'error' });
    if (!password) tempMessages.push({ message: 'Your password is missing', type: 'error' });

    if (tempMessages.length > 0) {
      setMessages(tempMessages);
      return;
    }

    const formData = {
      email: email,
      password: password
    };

    try {
      const response = await apiService.postWithoutToken('/login/', JSON.stringify(formData));
      if (response.data.access) {
        handleLogin(response.data.access, response.data.refresh);
        setMessages([{ message: 'Login success! You will be redirected.', type: 'success' }]);
        //router.push('/'); // Redirection après succès
      } else {
        const tmpErrors: Message[] = Object.values(response.data)
          .map((error: any) => ({ message: error, type: 'error' }));
        setMessages(tmpErrors);
      }
    } catch (error) {
      setMessages([{ message: 'An error occurred. Please try again.', type: 'error' }]);
    }
  };

  return (





Login



             setEmail(e.target.value)}
            />



             setPassword(e.target.value)}
            />

          {messages.length > 0 && (


              {messages.map((msg, index) => (


                  {msg.message}

              ))}

          )}

            Log In




