"use client";

import { useState } from "react";
import apiService from "@/libs/apiService";
import { Application } from "@/types";

interface ApplicationsReviewClientProps {
  initialApplications: Application[];
  jobId: string;
}

export default function ApplicationsReviewClient({
  initialApplications,
  jobId
}: ApplicationsReviewClientProps) {
  const [applications, setApplications] = useState(initialApplications);
  const [isLoading, setIsLoading] = useState<Record>({});

  const reviewApplication = async (
    applicationId: string, 
    status: "Accepted" | "Rejected"
  ): Promise => {
    try {
      setIsLoading(prev => ({ ...prev, [applicationId]: true }));

      const response = await apiService.post( `/job/review_application/${applicationId}/${status}/`,'' );

      const updatedApp: Application = response.data;

      setApplications(prev => {
        const index = prev.findIndex(app => app.id === updatedApp.id);
        if (index === -1) return prev;

        const updated = [...prev];
        updated[index] = updatedApp;
        return updated;
      });
    } catch (error) {
      console.error("Error reviewing application:", error);
    } finally {
      setIsLoading(prev => ({ ...prev, [applicationId]: false }));
    }
  };

  if (applications.length === 0) {
    return (

No applications found for this job.
    );
  }

  const jobInfo = applications[0]?.job;

  return (
    <>
      {jobInfo && (


          {jobInfo.title} at{" "}
          {jobInfo.company_name}

      )}



        {applications.map((app) => (







{app.name}

{app.email}


                {app.status}




{app.message}


              View Resume


            {app.status === "Pending" && (


                 reviewApplication(app.id, "Accepted")}
                  disabled={isLoading[app.id]}
                  className={`px-4 py-2 bg-green-600 text-white rounded-lg transition-colors ${
                    isLoading[app.id]
                      ? "opacity-50 cursor-not-allowed"
                      : "hover:bg-green-700"
                  }`}
                >
                  {isLoading[app.id] ? "Processing..." : "Accept"}

                 reviewApplication(app.id, "Rejected")}
                  disabled={isLoading[app.id]}
                  className={`px-4 py-2 bg-red-600 text-white rounded-lg transition-colors ${
                    isLoading[app.id]
                      ? "opacity-50 cursor-not-allowed"
                      : "hover:bg-red-700"
                  }`}
                >
                  {isLoading[app.id] ? "Processing..." : "Reject"}


            )}

        ))}

    </>
  );
}

  const getStatusStyles = (status: Application["status"]): string => {
    switch (status) {
      case "Accepted":
        return "bg-green-100 text-green-700";
      case "Rejected":
        return "bg-red-100 text-red-700";
      default:
        return "bg-yellow-100 text-yellow-700";
    }
  };



"use client"

import { useState, FormEvent, ChangeEvent } from "react";
import apiService from "@/libs/apiService";
import { toast } from "sonner";

type FormData = {
  fullname: string;
  email: string;
  message: string;
  resume: File | null;
};

export default function JobApplicationForm({
  jobId,
  initialHasApplied
}: {
  jobId: string;
  initialHasApplied: boolean
}) {
  const [form, setForm] = useState({
    fullname: "",
    email: "",
    message: "",
    resume: null,
  });
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitStatus, setSubmitStatus] = useState<{ success: boolean; message: string } | null>(null);
  const [hasApplied, setHasApplied] = useState(initialHasApplied);

  const handleInputChange = (e: ChangeEvent) => {
    const { name, value } = e.target;
    setForm(prev => ({ ...prev, [name]: value }));
  };

  const handleFileChange = (e: ChangeEvent) => {

    const file = e.target.files?.[0];
    if (file) {
    setForm(prev => ({ ...prev, resume: file }));
    }


    // if (e.target.files && e.target.files.length > 0 ) {
    //   setForm(prev => ({ ...prev, resume: e.target.files[0] }));
    // }

  };

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    setSubmitStatus(null);

    try {
      const formData = new FormData();
      formData.append('name', form.fullname);
      formData.append('email', form.email);
      formData.append('message', form.message);
      if (form.resume) { formData.append('resume', form.resume); }

      const response = await apiService.fetch_proxy( 'POST', `/job/create_application/${jobId}`, formData, );

      setSubmitStatus({ success: true, message: "Application submitted successfully!" });
      setHasApplied(true);

      setForm({
        fullname: "",
        email: "",
        message: "",
        resume: null,
      });
    } catch (error) {
      console.error("Error submitting application:", error);
      setSubmitStatus({
        success: false,
        message: "Failed to submit application. Please try again."
      });
    } finally {
      setIsSubmitting(false);
    }

  };

  return (




Apply for this job

        {submitStatus && (


            {submitStatus.message}

        )}



          Name





          Email





          Message





          Resume (PDF/DOC)



        {hasApplied ? (

✅ Already applied
        ) : (

            {isSubmitting ? 'Submitting...' : 'Submit Application'}

        )}


  );
}



"use client"; 

import { useState, useEffect } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import type { FormEvent, ChangeEvent } from 'react';

export default function JobFilters() {
    const router = useRouter();
    const searchParams = useSearchParams();

    const [title, setTitle] = useState(searchParams.get('title') || "");
    const [location, setLocation] = useState(searchParams.get('location') || "");
    const [datePosted, setDatePosted] = useState(searchParams.get('datePosted') || "all");
    const [experience, setExperience] = useState(searchParams.get('experience') || "all");
    const [jobType, setJobType] = useState(searchParams.get('jobType') || "all");


    const updateSearchParams = () => {
        const params = new URLSearchParams(searchParams.toString());
        params.set('title', title);
        params.set('location', location);
        params.set('datePosted', datePosted);
        params.set('experience', experience);
        params.set('jobType', jobType);

        router.push(`/jobs/search?${params.toString()}`);
    };

    useEffect(() => {
        const hasChanged = searchParams.get('datePosted') !== datePosted || 
                           searchParams.get('experience') !== experience || 
                           searchParams.get('jobType') !== jobType;

        if (hasChanged) {
            updateSearchParams();
        }
    // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [datePosted, experience, jobType]);

    const handleSubmit = (e: FormEvent) => {
        e.preventDefault();
        updateSearchParams();
    };

    return (




                    <input
                        type="search"
                        placeholder="Find a job..."
                        value={title}
                        onChange={(e: ChangeEvent) => setTitle(e.target.value)}
                        className="w-full px-6 py-4 rounded-xl border"
                    />








Filters



                    Location
                    <input
                        type="text"
                        placeholder="e.g. Paris"
                        value={location}
                        onChange={(e: ChangeEvent) => setLocation(e.target.value)}
                        className="w-full border border-gray-300 rounded p-2"
                    />




                    Date posted
                    <select value={datePosted} onChange={(e: ChangeEvent) => setDatePosted(e.target.value)} className="w-full border border-gray-300 rounded p-2">
                        Any time
                        Last 24 hours
                        Last 3 days
                        Last 7 days
                        Last 30 days





                    Experience
                    <select value={experience} onChange={(e: ChangeEvent) => setExperience(e.target.value)} className="w-full border border-gray-300 rounded p-2">
                        All
                        Entry Level
                        Mid Level
                        Senior





                    Employment Type
                    <select value={jobType} onChange={(e: ChangeEvent) => setJobType(e.target.value)} className="w-full border border-gray-300 rounded p-2">
                        All
                        Permanent
                        Temporary
                        Freelance
                        Internship




    );
}



'use client';

import { useState } from "react";
import type { FormEvent, ChangeEvent } from 'react'; 
import apiService from "@/libs/apiService";
import { useRouter } from 'next/navigation';
import { Job } from "@/types";

interface Message {
  message: string;
  type: 'error' | 'success';
}



interface JobFormProps {
    mode: 'create' | 'edit';
    jobId?: string;
    initialData?: Partial;
}

export default function JobForm({ mode, jobId, initialData }: JobFormProps) {
    const router = useRouter();

    // États du formulaire
    const [title, setTitle] = useState(initialData?.title || "");
    const [companyName, setCompanyName] = useState(initialData?.company_name || "");
    const [location, setLocation] = useState(initialData?.location || "");
    const [salary, setSalary] = useState(initialData?.salary || "");
    const [employmentType, setEmploymentType] = useState(initialData?.employment_type || "");
    const [experienceLevel, setExperienceLevel] = useState(initialData?.experience_level || "");
    const [description, setDescription] = useState(initialData?.description || "");
    const [requirements, setRequirements] = useState(
        initialData?.requirements ? initialData.requirements.join("\n") : ""
    );
    const [messages, setMessages] = useState([]);
    const [isLoading, setIsLoading] = useState(false);


    const validateForm = (): Message[] => {
        const tempMessages: Message[] = [];
        if (!title.trim()) tempMessages.push({ message: 'Title is missing', type: 'error' });
        if (!companyName.trim()) tempMessages.push({ message: 'Company name is missing', type: 'error' });
        if (!location.trim()) tempMessages.push({ message: 'Location is missing', type: 'error' });
        if (!employmentType.trim()) tempMessages.push({ message: 'Employment type is missing', type: 'error' });
        if (!experienceLevel.trim()) tempMessages.push({ message: 'Experience level is missing', type: 'error' });
        if (!salary.trim()) tempMessages.push({ message: 'Salary is missing', type: 'error' });
        if (!description.trim()) tempMessages.push({ message: 'Description is missing', type: 'error' });
        if (!requirements.trim()) tempMessages.push({ message: 'Requirements are missing', type: 'error' });
        return tempMessages;
    };

    const handleSubmit = async () => {
        setIsLoading(true);
        setMessages([]); 

        const validationErrors = validateForm();
        if (validationErrors.length > 0) {
            setMessages(validationErrors);
            setIsLoading(false);
            return;
        }

        const formData: Partial = {
            title,
            company_name: companyName,
            location,
            salary,
            employment_type: employmentType,
            experience_level: experienceLevel,
            description,
            requirements: requirements.split("\n").filter(line => line.trim() !== "")
        };

        try {
            const endpoint = mode === 'create' 
                ? '/job/create_job/' 
                : `/job/edit_job/${jobId}/`;

            const method = mode === 'create' ? 'post' : 'put';

            const response = await apiService[method](endpoint, formData);

            if (response.success) {
                const successMessage = mode === 'create' 
                    ? 'Job created! You will be redirected...'
                    : 'Job updated! You will be redirected...';

                setMessages([{ message: successMessage, type: 'success' }]);

                setTimeout(() => {
                    router.push('/jobs/myjobs');
                }, 2000);
            } else if (response.errors) {
                const tmpErrors: Message[] = Object.values(response.errors).map((errorMsg: any) => ({
                    message: errorMsg,
                    type: 'error'
                }));
                setMessages(tmpErrors);
            }
        } catch (error) {
            console.error("API call failed:", error);
            setMessages([{ 
                message: `An unexpected error occurred while ${mode === 'create' ? 'creating' : 'updating'} the job. Please try again.`, 
                type: 'error' 
            }]);
        } finally {
            if (!messages.some(m => m.type === 'success')) {
               setIsLoading(false);
            }
        }
    };

    const handleFormSubmit = (e: FormEvent) => {
        e.preventDefault();
        handleSubmit();
    };

    const pageTitle = mode === 'create' ? 'Create Job' : 'Edit Job';
    const submitButtonText = mode === 'create' ? 'Create Job' : 'Update Job';
    const loadingText = mode === 'create' ? 'Creating...' : 'Updating...';

    return (



{pageTitle}




                    Title
                    <input
                        value={title}
                        onChange={(e: ChangeEvent) => {setTitle(e.target.value)}}
                        type="text"
                        className="w-full mt-2 p-4 rounded-xl bg-gray-100"
                        disabled={isLoading}
                    />




                    Company name
                    <input
                        value={companyName}
