                        value={experienceLevel}
                        onChange={(e: ChangeEvent) => {setExperienceLevel(e.target.value)}}
                        className="w-full mt-2 p-4 rounded-xl bg-gray-100"
                        disabled={isLoading}
                    >
                        Select experience
                        Junior
                        Mid
                        Senior





                    Salary
                    <input
