                        type="text"
                        className="w-full mt-2 p-4 rounded-xl bg-gray-100"
                        disabled={isLoading}
                    />




                    Description
                    <textarea
                        value={description}
                        onChange={(e: ChangeEvent) => {setDescription(e.target.value)}}
                        className="w-full mt-2 p-4 rounded-xl bg-gray-100"
                        rows={5}
                        disabled={isLoading}
                    />




                    Requirements
