'use server'
import { MyJwtPayload } from '@/types';
import { jwtDecode } from 'jwt-decode';
import { cookies } from 'next/headers';
import { redirect } from 'next/navigation';


export async function handleLogin(accessToken: string, refreshToken: string) {
    (await cookies()).set('session_access_token', accessToken, {
        httpOnly: true,
        secure: false,
        maxAge: 60 * 1, // 1 minutes
        path: '/'
    });

    (await cookies()).set('session_refresh_token', refreshToken, {
        httpOnly: true,
        secure: false,
        maxAge: 60 * 60 * 24 * 1, // One day
        path: '/'
    });

    redirect('/');
}

export async function getAccessToken() {
    let accessToken = (await cookies()).get('session_access_token')?.value;
    return accessToken;
}

export async function getUserInfo() {
    let user_id = "";
    let is_recruiter = false;

    const refreshToken = (await cookies()).get("session_refresh_token")?.value

    if (refreshToken) {
    user_id = jwtDecode(refreshToken).user_id
    is_recruiter = jwtDecode(refreshToken).is_recruiter
    };

    return {user_id, is_recruiter};
}

export async function logoutUser() {
  const cookieStore = await cookies();
  cookieStore.delete('session_access_token');
  cookieStore.delete('session_refresh_token');
  redirect('/');
}



import { getAccessToken } from "../libs/actions";
import { redirect } from 'next/navigation';


const apiService = {

async _request(url: string, method: string, data?: any): Promise {
        const token = await getAccessToken();
        const options: RequestInit = { method };

        const headers = new Headers();
        if (token) {
            headers.append('Authorization', `Bearer ${token}`);
        }

        if (data) {
            if (data instanceof FormData) {
                options.body = data;
            } else {
                headers.append('Content-Type', 'application/json');
                options.body = JSON.stringify(data);
            }
        }
        options.headers = headers;

        try {
            const response = await fetch(`${process.env.NEXT_PUBLIC_API_HOST}${url}`, options);

            if (!response.ok) {
                const errorData = await response.json().catch(() => ({ message: 'Erreur inconnue' }));
                throw new Error(`Erreur HTTP ${response.status}: ${errorData.detail || errorData.message}`);
            }

            if (response.status === 204) { 
                return null;
            }

            const json = await response.json();
            console.log('Response:', json);
            return json;

        } catch (error) {
            console.error(`Erreur de l'API (${method} ${url}):`, error);
            throw error; 
        }
    },

    get: function(url: string): Promise {
        return this._request(url, 'GET');
    },

    post: function(url: string, data: any): Promise {
        return this._request(url, 'POST', data);
    },

    delete: function(url: string): Promise {
        return this._request(url, 'DELETE');
    },

    put: function(url: string, data: any): Promise {
        return this._request(url, 'PUT', data);
    },


postWithoutToken: async function(url: string, data: any): Promise {

    return new Promise((resolve, reject) => {
        fetch(`${process.env.NEXT_PUBLIC_API_HOST}${url}`, {
            method: 'POST',
            body: data,
            headers: {
                'Accept': 'application/json',
                'Content-Type': 'application/json'
            }
        })
            .then(async(response) => {
                console.log('Response:', response);
                const parsedResponse = await response.json();
                resolve({
                status: response.status,
                data: parsedResponse
                });
            })
            .catch((error => {
                reject(error);
            }))
    })
},

fetch_proxy : async function (method: string, url: string , data?: any): Promise {

    const token = await getAccessToken();

    const options: RequestInit = { method };

    const headers = new Headers();
        if (token) {
            headers.append('Authorization', `Bearer ${token}`);
        }

        if (data) {
            if (data instanceof FormData) {
                options.body = data;
            } else {
                headers.append('Content-Type', 'application/json');
                options.body = JSON.stringify(data);
            }
        }
        options.headers = headers;


    const response = await fetch(`/api${url}`, options);


    if (response.status === 401) {
        console.log(typeof response.status)
        // redirect('/login');
        window.location.href = '/login'; 

    }

    if (!response.ok) {
        // Gérer les autres erreurs HTTP (404, 500, etc.)
        const errorData = await response.json().catch(() => ({ message: response.statusText }));
        const error = new Error(`Erreur HTTP ${response.status}: ${errorData.message || response.statusText}`);
        throw error;
    }

    // Si la réponse peut être vide (ex: statut 204 No Content)
    if (response.status === 204) {
        return null;
    }

    const json = await response.json();
    console.log('Response:', json);
    return json;

  },

}

export default apiService;



// middleware.js
import { jwtDecode } from 'jwt-decode';
import { NextRequest, NextResponse } from 'next/server';
import { MyJwtPayload } from './types';

const publicPaths = ['/', '/jobs/[id]', '/jobs/search'];

export async function middleware(req: NextRequest) {

    const path = req.nextUrl.pathname;
    const isPublicPath = publicPaths.includes(path) || path.startsWith('/jobdetail/');

    let accessToken = req.cookies.get('session_access_token')?.value;
    const refreshToken = req.cookies.get('session_refresh_token')?.value;

    console.log("-----in middleware")
    // Si on a déjà un access token valide → continuer
    if (accessToken && !isExpired(accessToken)) {
        return NextResponse.next();
    }

    console.log("-----invalid access token")
    // Pas d'access token mais on a un refresh token → essayer de rafraîchir
    if (refreshToken) {
        try {
            const refreshResponse =  await fetch(`${process.env.NEXT_PUBLIC_API_HOST}/refresh/`, {
                method: 'POST',
                headers: {
                    'Accept': 'application/json',
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({ refresh: refreshToken })
            });

            const json = await refreshResponse.json();

            if (json.access) {

                const res = NextResponse.redirect(req.url);
                res.cookies.set('session_access_token', json.access, {
                    httpOnly: true,
                    secure: false, 
                    maxAge: 60 * 1, // 1 min
                    path: '/'
                });

                return res;
            } 
        } catch (error) {
            console.error('Erreur refresh token:', error);
            // Tomber dans le cas d'erreur 401 plus bas
        }
    }

    // Pas de refresh token → redirection login

    if (req.nextUrl.pathname.startsWith('/api/')) {
        // Pour les appels API, on renvoie une erreur 401.
        // Api car on veut intercepter uniquement le on click
        console.log(`[Middleware] API request to ${req.nextUrl.pathname} denied with 401.`);
        const response = NextResponse.json(
            { message: 'Authentication required' },
            { status: 401 }
        );
        response.cookies.delete('session_access_token');
        response.cookies.delete('session_refresh_token');

        //const response = NextResponse.redirect(loginUrl); // cannot redirect because it's not the navigator who send the request
        return response;

    } else if ( !isPublicPath ) {
        // Pour les navigations de page, on redirige vers le login.
        console.log(`[Middleware] Page navigation to ${req.nextUrl.pathname} redirected to /login.`);
        const loginUrl = new URL('/login', req.url);

        const response = NextResponse.redirect(loginUrl);

        response.headers.set('Refresh', `0; url=${loginUrl.pathname}`);    
        response.cookies.delete('session_access_token');
        response.cookies.delete('session_refresh_token');
        return response;
    }

    return NextResponse.next();

}

function isExpired(token: string) {
  try {
    const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString());
    return payload.exp * 1000 < Date.now();
  } catch {
    return true;
  }
}



